-- 001: upstream v9.3.0 -> custom duty schema. Back up first.
-- Run once only; existing custom installations use runtime AutoMigrate.
-- Requires a fully initialized upstream database with notify_rule present.
ALTER TABLE notify_rule ADD COLUMN receiver_mode varchar(20) DEFAULT 'original';
ALTER TABLE notify_rule ADD COLUMN duty_group_id bigint DEFAULT 0;
CREATE TABLE `response_claim_notice` (`group_id` bigint,`id` bigint AUTO_INCREMENT,`dedup_key` varchar(64),`response_id` bigint,`event_id` bigint,`group_name` longtext,`title` longtext,`claimant` longtext,`claimed_at` bigint,`timezone` longtext,`destination` text,`status` varchar(20),`started_at` bigint,`finished_at` bigint,`reason` longtext,PRIMARY KEY (`id`),INDEX `idx_response_claim_notice_response_id` (`response_id`),INDEX `idx_response_claim_notice_status` (`status`),UNIQUE INDEX `idx_response_claim_notice_dedup_key` (`dedup_key`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_duty_audit` (`id` bigint AUTO_INCREMENT,`group_id` bigint,`actor` longtext,`action` longtext,`version` bigint,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_response_duty_audit_group_id` (`group_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_duty_group` (`id` bigint AUTO_INCREMENT,`name` varchar(80),`config` text,`secrets` text,`version` bigint,`updated_at` bigint,`updated_by` longtext,PRIMARY KEY (`id`),UNIQUE INDEX `idx_response_duty_group_name` (`name`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_duty_notice` (`id` bigint AUTO_INCREMENT,`dedup_key` varchar(64),`kind` longtext,`group_id` bigint,`response_id` bigint,`assignment_version` bigint,`rule_id` bigint,`channel_id` bigint,`config_index` bigint,`recipient` longtext,`status` varchar(20),`reason` longtext,`payload` text,`created_at` bigint,`started_at` bigint,`finished_at` bigint,`expires_at` bigint,PRIMARY KEY (`id`),INDEX `idx_response_duty_notice_group_id` (`group_id`),INDEX `idx_response_duty_notice_response_id` (`response_id`),INDEX `idx_response_duty_notice_status` (`status`),UNIQUE INDEX `idx_response_duty_notice_dedup_key` (`dedup_key`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_duty_reminder_clock` (`group_id` bigint AUTO_INCREMENT,`next_at` bigint,PRIMARY KEY (`group_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_duty_settings` (`id` bigint AUTO_INCREMENT,`fallback` text,`version` bigint,`secrets` text,PRIMARY KEY (`id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_event_log` (`id` bigint AUTO_INCREMENT,`response_id` bigint,`actor` longtext,`action` longtext,`content` text,`created_at` bigint,PRIMARY KEY (`id`),INDEX `idx_response_event_log_response_id` (`response_id`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `response_event` (`assignment_version` bigint,`id` bigint AUTO_INCREMENT,`episode` varchar(160),`hash` varchar(128),`first_trigger_time` bigint,`owner_id` bigint,`owner_name` longtext,`recovered` boolean,`unclaimed_since` bigint,`version` bigint,`updated_at` bigint,PRIMARY KEY (`id`),INDEX `idx_response_event_hash` (`hash`),UNIQUE INDEX `idx_response_event_episode` (`episode`))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
